<form method="post" action="<?= e(APP_URL.'/families/'.(int)$family['family_id'].'/guardianship/create') ?>" class="space-y-6"><section class="rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><label class="text-sm font-medium text-slate-700">Adult family member<select required name="person_id" class="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm"><option value="">Select adult member</option><?php foreach($candidates??[] as $c): ?><option value="<?= (int)$c['person_id'] ?>"><?= e($c['full_name'].' · '.($c['nic']?:'No NIC')) ?></option><?php endforeach; ?></select></label><p class="mt-3 text-sm text-slate-500">This marks the person as a household guardian. A separate guardianship table is required to assign one guardian to one specific child with start/end dates.</p></section><div class="flex justify-end gap-3"><a href="<?= e(APP_URL.'/families/'.(int)$family['family_id'].'/guardianship') ?>" class="rounded-lg border border-slate-300 px-4 py-2.5 text-sm font-semibold">Cancel</a><button class="rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white">Designate Guardian</button></div></form>
